      "type": "좌담회",
      "raw_content": "카페홈\n좌담회/설문/주부알바\n가입\n검색\n메뉴\n▶설문 신청(당일 현금)~아시분과 신청가능\n앱 열기\n▶9/1~) 생활용품 유치 조사 / 만20세~55세 기혼 여성 (20대는 1인가구 미혼 가능)\n본문 기타 기능\n하늘\n카페매니저\n채팅\n작성일\n2026.08.18. 15:51\n조회 77\n▶9/1~) 생활용품 유치 조사 / 만20세~55세 기혼 여성 (20대는 1인가구 미혼 가능)\n=====================================\n기본 조건\n댁 내 생활용품 구매 결정자\n조사 일정중 정해진 가이드에 따라 성실히 참여 해주실 분\n임신/수유중, 알러지, 호흡기 질환자는 참여 불가\n-------------------------------------------------------------------\n조사 일정\n9월1일~약 2주간, 보내 드리는 섬유유연제를 사용후 온라인 설문 참여\n9월1~20일 여행,출장등 집을 비우는 계획이 없으신 분\n-------------------------------------------------------------------\n조사 방법\n1.제품을 댁으로 발송해 드림\n2.정해진 가이드에 따라 제품 사용후 총 3번의 온라인 설문 ( 온라인 설문은 각 차수별 10분 소요)\n3. 조사 응답후 제품 발송해 주셔야 최종 완료 ( 회수가 되지 않거나, 분실시 사례비 지급하지 않습니다 )\n-------------------------------------------------------------------\n사례비\n3만5천원 ( 사용 후 제품 선불 발송비 포함)\n##신청후 섬유 유연제 사진 (섬유유연제가 놓여진 장소 확인 가능하도록, 전체샷+ 제품 확대샷, 최소 2장이상)을 아래 링크에 올려주신 분들 우선적으로 연락 드리겠습니다\nhttps://tally.so/r/ODx4ag\n-------------------------------------------------------------------\n▶기재 사항\n성명/연락처/이메일/생년월일/거주지_ 동까지/혼인여부/ 직업 / 가족구성_유자녀는 자녀 나이 모두 / 1주 평균_ 세탁 횟수( 세탁기사용기준) / 1주평균_ 섬유유연제 사용 횟수 / 건조기 유무 / 현재 사용중인 섬유유연제 모두 / 주사용 섬유유연제 ( 브랜드+ 향_ 정확하게 기입)\n-\n[아래 URL에 (클릭!!)하여 신청해 주세요].(스마트폰도 가능!!)]\nhttps://forms.gle/9egxu7K7pcWvRsCa6\n좋아요\n1\n좋아요한 사람 목록으로 이동\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n지금 가입하고 댓글에 참여해보세요!\n전체글\n▶8/21 ]금융앱 관련 좌담회 /만 55~65세 남,여\n하늘\n26.08.18.\n댓글\n0\n▶9/1~) 생활용품 유치 조사 / 만20세~55세 기혼 여성 (20대는 1인가구 미혼 가능)\n하늘\n26.08.18.\n댓글\n0\n▶9월 둘째주 ]위고비, 마운자로 사용자 및 중단자 좌담회 /20~59세 남/여\n하늘\n26.08.18.\n댓글\n0\n▶추후협의 ]자동차 서비스센터 방문예정자 미스테리 조사\n하늘\n26.08.18.\n댓글\n0\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n좌담회/설문/주부알바\n 카페에 가입해 보세요!\n가입하면 1만개의 글을 볼 수 있어요\n10초 만에 가입하기\n목록으로\n좋아요\n1\n좋아요한 사람 목록으로 이동\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
