      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n수정&재공지 좌담/설문\n앱 열기\n30만)퇴직 전문인력의 계속고용을 위한 직업능력 향상 방안 FGI 조사\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.08.18. 10:03\n조회 104\n구독\n30만)퇴직 전문인력의 계속고용을 위한 직업능력 향상 방안 FGI 조사\n신청하신분은 재신청 안하셔도 됩니다\n대상자 조건\n공통 조건\n55세 이상 중고령자\n현 직장에서 10년 이상 경력\n2년 이내 퇴직이 예정되어 있는 사람 or 1년 미만 퇴직자인데 구직자\n대기업(1,000인 이상)\n1그룹 화이트 (관리·기획직) : 인사, 재무, 경영기획, 총무 – 부장급 이상\n2그룹 블루 (전문·기술직) : R&D, IT, 생산기술, 품질관리 – (관련 자격증을 보유했거나 석사 이상 학력) & 부장급 이상\n3그룹 화이트 (금융·보험업) : 은행, 보험 등 금융관련 전문가 – 부장급 이상\n중소기업(300인 미만)\n4그룹 화이트 (관리·기획직) : 인사, 재무, 경영기획, 총무 – 부장급 이상\n5그룹 : 블루칼라(기업규모 무관)\n5그룹 블루 (현장전문가) 기능사 이상 국가기술자격 보유 현장직, 퇴직 예정 사유는 건강이 아닌 정년, 계약만료, 사업장 이전 등\n* 소요시간 : 약 2시간\n* 모집 인원 : 각 그룹 별 6명\n* 사례비 : 30만원(세전금액), 사례비 지급을 위한 통장사본, 신분증사본 지참 필수\n* 진행장소 : 서울 강남구 역삼동 부근(역삼역/언주역 도보 10분 이내)\n* 신청양식 : 이름/연락처/출생년도(나이)/성별/회사명(업종)/직급/직종(직무)\n* 소속 및 대상 여부 확인 등 사전 연락을 통해 최종 확정 안내 된 분에 한해서 참여\nhttps://forms.gle/JTnC5UytivtS49FH8\n좋아요\n0\n송파구에서 많이 본 동네소식 보러가기\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.08.18. 14:39 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n고유링크) 여성: 18~24세 / 45세 이상) 생성형 AI 대규모 커뮤니티 조사\n좌담회알바좌담회카페\n26.08.18.\n댓글\n1\n30만)퇴직 전문인력의 계속고용을 위한 직업능력 향상 방안 FGI 조사\n좌담회알바좌담회카페\n26.08.18.\n댓글\n1\n만19세 남녀 청소년(대학교2학년)음료관련 온라인 커뮤니티(8/마지막주)+좌담회(9/5)\n좌담회알바좌담회카페\n26.08.17.\n댓글\n1\n만18세 남녀 청소년(대학교1학년)음료관련 온라인 커뮤니티(8/마지막주)+좌담회(9/5)\n좌담회알바좌담회카페\n26.08.17.\n댓글\n1\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n수정&재공지 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n0\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
