      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n고유링크) 8/27~9/1) 만30~39세 남성) 청년세대의 생애 경로 좌담회(수도권 및 지방 거주자 대상)\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.08.18. 16:25\n조회 86\n구독\n고유링크) 8/27~9/1) 만30~39세 남성) 청년세대의 생애 경로 좌담회(수도권 및 지방 거주자 대상)\n고유링크) 8/27~9/1) 만19~39세 남녀(직업 무관, 지역 무관, 성별 무관) 청년세대의 생애 경로 좌담회(수도권 및 지방 거주자 대상)\n참여조건\n[한국리서치 본사에서 오프라인으로 진행하는 좌담회입니다.]\n청년 세대의 진로/경력/대인관계/온라인경험/여가 등 전반적인 생활에 대해 얘기를 나누는 자리입니다.\n강남구 논현동에 위치한 한국리서치 본사에서 진행됩니다. 비수도권 거주자의 경우 교통비를 추가적으로 지급해드릴 예정입니다.\n▶조사 대상 : 만 19~39세 남녀(직업 무관, 지역 무관, 성별 무관)\n▶진행 방식 : 오프라인 좌담회\n▶일정: 8월 27일(목), 8월 31일(월), 9월 1일(화) 중 조건에 따라 상이(추후 안내)\n▶소요시간: 2시간 / 사례비: 5만원(비수도권 거주자의 경우 교통비 추가 지급)\n▶조사 장소 : 한국리서치 본사(9호선 언주역 인근)\n★신청해 주신 내용을 토대로 순차적으로 전화 드릴 예정입니다. 저희 직원과 통화 후 참여자 명단에 등록이 되셔야 참여 가능합니다.\n조사장소 강남구 논현동 한국리서치 본사 (9호선:언주역)\n조사기간 2026-08-27 ~ 2026-09-01일 중 하루 /시간은 추후 안내드립니다\n소요시간 2시\n사례비 50,000원\n조사방법 2시간 좌담회\n안내사항 성별/연령대별 일정이 달라 추후 안내드릴 예정입니다.\n조사 참여 고유링크\nhttps://www.hrc-ms.com/participate/improSurvey/768?refuser=23341&intro=2\n좋아요\n1\n좋아요한 사람 목록으로 이동\n송파구 이웃끼리 공유하는 동네 꿀정보\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.08.18. 17:25 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n9월~ ) 만20세~55세 기혼 여성) 생활용품 유치 조사\n좌담회알바좌담회카페\n26.08.18.\n댓글\n1\n고유링크) 8/27~9/1) 만30~39세 남성) 청년세대의 생애 경로 좌담회(수도권 및 지방 거주자 대상)\n좌담회알바좌담회카페\n26.08.18.\n댓글\n1\n고유링크) 8/27~9/1) 만30~39세 여성) 청년세대의 생애 경로 좌담회(수도권 및 지방 거주자 대상)\n좌담회알바좌담회카페\n26.08.18.\n댓글\n1\n고유링크) 8/27~9/1) 만19~29세 여성) 청년세대의 생애 경로 좌담회(수도권 및 지방 거주자 대상)\n좌담회알바좌담회카페\n26.08.18.\n댓글\n1\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n1\n좋아요한 사람 목록으로 이동\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
