      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n고유링크)9/2~4)안전·건강 케어 서비스 관련 소비자 좌담회-시니어그룹:만65세 이상 여성 중 독립적으로 거주하거나 가족과 동거하더라도 일정 시간 돌봄 공백이 있는 자\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.08.18. 18:36\n조회 57\n구독\n고유링크)9/2~4)안전·건강 케어 서비스 관련 소비자 좌담회-시니어그룹:만65세 이상 남녀 중 독립적으로 거주하거나 가족과 동거하더라도 일정 시간 돌봄 공백이 있는 자\n자녀 그룹 : 만 30~64세 남녀 중 만 65세 이상 부모 또는 가족의 돌봄,안전 관리에 관여하는 자\n시니어 그룹 : 만 65세 이상 남녀 중 독립적으로 거주하거나 가족과 동거하더라도 일정 시간 돌봄 공백이 있는 자\n참여조건\n[한국리서치 본사에서 오프라인으로 진행하는 좌담회입니다.]\n조사 일정 : 9월 2일 (수) ~ 9월 4일 (금)중 하루 / 시간은 확정시 안내드립니다\n조건 대상 :\n자녀 그룹 : 만 30~64세 남녀 중 만 65세 이상 부모 또는 가족의 돌봄,안전 관리에 관여하는 자\n시니어 그룹 : 만 65세 이상 남녀 중 독립적으로 거주하거나 가족과 동거하더라도 일정 시간 돌봄 공백이 있는 자\n★신청해 주신 내용을 토대로 순차적으로 전화 드릴 예정입니다. 저희 직원과 통화 후 참여자 명단에 등록이 되셔야 참여 가능합니다.\n조사장소 강남구 논현동 한국리서치 본사 (9호선:언주역)\n조사기간 2026-08-18 ~ 2026-09-04일 중 하루 / 시간은 추후 안내드립니다\n소요시간 120분\n사례비 60,000원\n조사방법 2시간 좌담회\n안내사항 댁 내 안전,응급,건강 중심 Lifecare 서비스 관련한 소비자 의견을 파악하는 조사입니다.\n조사 참여 고유링크\nhttps://www.hrc-ms.com/participate/improSurvey/766?refuser=23341&intro=2\n좋아요\n1\n좋아요한 사람 목록으로 이동\n송파구에서 핫한 진짜 동네 이야기\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n8/24~25) 25-44세 여성)스킨케어 화장품(에센스or세럼or앰플or 크림) 구매사용자 좌담회\n좌담회알바좌담회카페\n26.08.18.\n댓글\n0\n고유링크)9/2~4)안전·건강 케어 서비스 관련 소비자 좌담회-시니어그룹:만65세 이상 여성 중 독립적으로 거주하거나 가족과 동거하더라도 일정 시간 돌봄 공백이 있는 자\n좌담회알바좌담회카페\n26.08.18.\n댓글\n0\n고유링크)9/2~4)안전·건강 케어 서비스 관련 소비자 좌담회-시니어그룹:만65세 이상 남성 중 독립적으로 거주하거나 가족과 동거하더라도 일정 시간 돌봄 공백이 있는 자\n좌담회알바좌담회카페\n26.08.18.\n댓글\n0\n고유링크)9/2~4)안전·건강 케어 서비스 관련 소비자 좌담회-자녀그룹:만30~64세 여성 중 만65세 이상 부모 또는 가족의 돌봄,안전 관리에 관여하는 자\n좌담회알바좌담회카페\n26.08.18.\n댓글\n0\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n좌담회알바좌담회카페\n 님\n의 글을 3개 보셨네요. 👀\n구독하고 새로운 글을 놓치지 마세요!\n멤버 구독하기\n목록으로\n좋아요\n1\n좋아요한 사람 목록으로 이동\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
