      "type": "온라인",
      "raw_content": "[비대면] 섬유유연제 사용 유치조사-만20~55세 여성 9/1~약 2주[3만5천원]\n​\n보다 안정적인 서비스 제공과 회원 맞춤 일감 안내를 위해 신청 시스템이 개선되었습니다.\n기존과 동일하게 신청해 주시면 됩니다.\n​\n대상 : 만20세~55세 기혼 여성 (20대는 1인가구 미혼 가능)\n댁 내 생활용품 구매 결정자\n조사 일정중 정해진 가이드에 따라 성실히 참여 해주실 분\n임신/수유중, 알러지, 호흡기 질환자는 참여 불가\n9월1~20일 여행,출장등 집을 비우는 계획이 없으신 분\n일정 : 9월1일~약 2주간, 보내 드리는 섬유유연제를 사용후 온라인 설문 참여\n방법 : 제품 사용 후 온라인 설문\n소요시간 : 온라인 설문 각 차수별 10분 소요\n사례비 : 3만5천원 ( 사용 후 제품 선불 발송비 포함)\n안내사항\n1.제품을 댁으로 발송해 드림\n2.정해진 가이드에 따라 제품 사용후 총 3번의 온라인 설문 ( 온라인 설문은 각 차수별 10분 소요)\n3. 조사 응답후 제품 발송해 주셔야 최종 완료( 회수가 되지 않거나, 분실시 사례비 지급하지 않습니다 )\n​\n신청후 섬유 유연제 사진\n(섬유유연제가 놓여진 장소 확인 가능하도록, 전체샷+ 제품 확대샷, 최소 2장이상)을\n아래 링크에 올려주신 분들 우선적으로 연락 드리겠습니다\n사진 먼저 전달\n​\n​\n신청하기",
