      "type": "좌담회",
      "raw_content": "# # 청년세대의 생애 경로 좌담회\n청년 세대의 진로/경력/대인관계/온라인경험/여가 등 전반적인 생활에 대해 얘기를 나누는 자리입니다.\n강남구 논현동에 위치한 한국리서치 본사에서 진행됩니다. 비수도권 거주자의 경우 교통비를 추가적으로 지급해드릴 예정입니다.\n*대상: 만 19~39세 남녀(직업 무관, 지역 무관, 성별 무관)\n*일정: 8월 27일(목), 8월 31일(월), 9월 1일(화) 중 조건에 따라 상이(추후 안내)\n*소요시간: 2시간\n*사례비: 5만원(비수도권 거주자의 경우 교통비 추가 지급)\n*장소: 한국리서치 본사(9호선 언주역 인근)\n<신청 방법>\n▷ 아래 URL에 접속하여 설문응답 진행해주세요. 신청해 주신 내용을 바탕으로 대상자가 되시면 저희가 순차적으로 전화 드립니다. 통화 후 참여 명단에 등록해드리며, 명단에 등록되셔야 참여 가능하니 참고 부탁드립니다.\nhttps://www.hrc-ms.com/participate/improSurvey/768?refuser=22336&intro=2\n글 탐색\n생활용품 유치 조사\n자녀를 양육중인 근로자 관련 조사",
