      "target_age": "",
      "target_gender": "",
      "target_condition": "FGI」를 실시하려 합니다.",
      "date": "8/26~9/6 (주말 포함)",
      "time": "이내",
      "duration": "",
      "reward": "10만원",
      "location": "",
      "type": "기타",
      "raw_content": "# # 자녀를 양육중인 근로자 관련 조사\n저희는 한국보건사회연구원의 의뢰를 받아 「일·돌봄 균형을 위한 자녀양육 근로자 부모 대상 FGI」를 실시하려 합니다.\n본 조사는 자녀를 양육하는 근로자의 일·돌봄 균형 실태 및 제도 수요 등을 파악하여 현 제도의 한계를 발굴하고 맞춤형 육아 지원을 위한 정책 수립의 기초자료를 확보하는데 목적이 있습니다.\n좌담회는 자녀를 양육하고 있는 근로자를 대상으로 진행되며, 평소 생활에 대해 자유롭게 의견을 나누는 자리입니다.\n*대상조건:\n초등학교 2학년 이하의 자녀를 양육하고있는 근로자\n(기간제∙일용직/ 특수형태근로종사자/ 자영업자 / 상용직 등) ;고용형태나 노동이력 고려\n*조사방법:\n– 대면 혹은 비대면(zoom)으로 진행되는 조사로 2시간 이내\n– 대면 또는 비대면 논의 예정\n– 대면인 경우 서초구 신반포로 303(리서치앤리서치)에서 진행 예정\n*일정: 8/26~9/6 (주말 포함)\n*사례비: 10만원\n<신청 방법>\n대상자 선정 설문 링크입니다. (인원이 차면 선착순 마감이 될수도 있고, 조건에 맞지 않는 대상자일 경우 설문이 종료될 수 있습니다)\n설문지 내에\n소개자이름\n기입란이 있으니\n유영두\n입력 바랍니다.\nhttps://survey.randr.co.kr/SurveyInOut/SurveyIn.aspx?cl=R1003&sid=15FBDF9442EF462F8A0FB52456F3F0EC\n글 탐색\n청년세대의 생애 경로 좌담회(수도권 및 지방 거주자 대상)\n스마트폰 통화 이용 경험 인터뷰 대상자 모집",
